// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListConnections Every connection with its last-opened time and unlock state
	// (GET /connections)
	ListConnections(w http.ResponseWriter, r *http.Request)
	// CreateConnection Create a connection and store its secret
	// (POST /connections)
	CreateConnection(w http.ResponseWriter, r *http.Request)
	// TestConnection Open a short-lived session with the given settings and report the server
	// (POST /connections/test)
	TestConnection(w http.ResponseWriter, r *http.Request)

	// (DELETE /connections/{connectionId})
	DeleteConnection(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)

	// (GET /connections/{connectionId})
	GetConnection(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)
	// UpdateConnection Update settings; the secret changes only when given
	// (PUT /connections/{connectionId})
	UpdateConnection(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)
	// ListAudit Writes Mesa ran on this connection, newest first
	// (GET /connections/{connectionId}/audit)
	ListAudit(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, params ListAuditParams)

	// (GET /connections/{connectionId}/databases)
	ListDatabases(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)
	// CreateDatabase Create an empty database (a reviewed write)
	// (POST /connections/{connectionId}/databases)
	CreateDatabase(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)
	// ApplyChanges Run a change set after policy approves it
	// (POST /connections/{connectionId}/databases/{database}/changes/apply)
	ApplyChanges(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName)
	// PlanChanges Compile a change set into SQL, risks and the policy decision
	// (POST /connections/{connectionId}/databases/{database}/changes/plan)
	PlanChanges(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName)
	// PlanScript Plan a hand-written SQL script as a change (statements, risks, policy decision)
	// (POST /connections/{connectionId}/databases/{database}/changes/script)
	PlanScript(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName)
	// ApplyScript Run a hand-written SQL script after policy approves it; audited like every write
	// (POST /connections/{connectionId}/databases/{database}/changes/script/apply)
	ApplyScript(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName)
	// GetDesignerModel The live schema as a model, its DBML and the saved diagram layout
	// (GET /connections/{connectionId}/databases/{database}/designer)
	GetDesignerModel(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName)
	// DiffDesignerModel Changes between the live schema and the edited model, planned as SQL
	// (POST /connections/{connectionId}/databases/{database}/designer/diff)
	DiffDesignerModel(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName)

	// (PUT /connections/{connectionId}/databases/{database}/designer/layout)
	SaveDesignerLayout(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName)

	// (POST /connections/{connectionId}/databases/{database}/explain)
	ExplainQuery(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName)

	// (GET /connections/{connectionId}/databases/{database}/monitor/overview)
	GetMonitorOverview(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName)
	// GetEnginePanel The engine-specific metrics panel
	// (GET /connections/{connectionId}/databases/{database}/monitor/panel)
	GetEnginePanel(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName)

	// (GET /connections/{connectionId}/databases/{database}/monitor/sessions)
	ListSessions(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName)
	// KillSession Cancel the running query, or terminate the backend
	// (POST /connections/{connectionId}/databases/{database}/monitor/sessions/{pid}/kill)
	KillSession(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName, pid int)
	// GetMonitorSnapshot Current metrics, rates since the previous sample, and the series for a range
	// (GET /connections/{connectionId}/databases/{database}/monitor/snapshot)
	GetMonitorSnapshot(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName, params GetMonitorSnapshotParams)
	// RunQuery Run SQL in a read-only transaction; writes go through changes/script
	// (POST /connections/{connectionId}/databases/{database}/query)
	RunQuery(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName)
	// QueryRows Page through a table with filters and sort
	// (POST /connections/{connectionId}/databases/{database}/rows)
	QueryRows(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName)
	// GetSchema The full model of the database, with stats
	// (GET /connections/{connectionId}/databases/{database}/schema)
	GetSchema(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName, params GetSchemaParams)
	// GetTable One table with fresh stats
	// (GET /connections/{connectionId}/databases/{database}/tables/{schema}/{table})
	GetTable(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, databaseName DatabaseName, schema string, table string)

	// (GET /connections/{connectionId}/history)
	ListHistory(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, params ListHistoryParams)
	// PingConnection Round trip to the server with the stored secret
	// (POST /connections/{connectionId}/ping)
	PingConnection(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)

	// (GET /connections/{connectionId}/roles)
	ListRoles(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)
	// CreateRole Create a role (a reviewed write)
	// (POST /connections/{connectionId}/roles)
	CreateRole(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)
	// DropRole Drop a role (a reviewed write)
	// (DELETE /connections/{connectionId}/roles/{role})
	DropRole(w http.ResponseWriter, r *http.Request, connectionId ConnectionId, role string, params DropRoleParams)
	// LockConnection End the unlock early
	// (DELETE /connections/{connectionId}/unlock)
	LockConnection(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)
	// UnlockConnection Allow writes on a read-only connection for a while
	// (POST /connections/{connectionId}/unlock)
	UnlockConnection(w http.ResponseWriter, r *http.Request, connectionId ConnectionId)
	// ParseDbml Parse DBML into a model (stateless)
	// (POST /designer/parse)
	ParseDbml(w http.ResponseWriter, r *http.Request)
	// PrintDbml Print a model as DBML (stateless)
	// (POST /designer/print)
	PrintDbml(w http.ResponseWriter, r *http.Request)

	// (GET /queries)
	ListSavedQueries(w http.ResponseWriter, r *http.Request)
	// SaveQuery Create or update a saved query (by id)
	// (PUT /queries)
	SaveQuery(w http.ResponseWriter, r *http.Request)

	// (DELETE /queries/{queryId})
	DeleteSavedQuery(w http.ResponseWriter, r *http.Request, queryId openapi_types.UUID)
	// GetSystemInfo Version, mode and capabilities of this Mesa
	// (GET /system/info)
	GetSystemInfo(w http.ResponseWriter, r *http.Request)
}

